const upsertArtifact = `-- name: UpsertArtifact :exec
INSERT INTO artifacts (id, execution_id, task_run_id, name, storage_key, size, content_type, created_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (task_run_id, name) DO UPDATE SET size = EXCLUDED.size, content_type = EXCLUDED.content_type, storage_key = EXCLUDED.storage_key
`

type UpsertArtifactParams struct {
	ID          uuid.UUID
	ExecutionID uuid.UUID
	TaskRunID   uuid.UUID
	Name        string
	StorageKey  string
	Size        int64
	ContentType string
	CreatedAt   time.Time
}

func (q *Queries) UpsertArtifact(ctx context.Context, arg UpsertArtifactParams) error {
	_, err := q.db.Exec(ctx, upsertArtifact,
		arg.ID,
		arg.ExecutionID,
		arg.TaskRunID,
		arg.Name,
		arg.StorageKey,
		arg.Size,
		arg.ContentType,
		arg.CreatedAt,
	)
	return err
}
